import styled from '@emotion/styled';
import { StyledTooltipContainer } from 'components/TooltipImage/TooltipImage.styles';

export const StyledGanttChartTooltip = styled(StyledTooltipContainer)({
  display: 'flex',
  flexDirection: 'column',
  fontSize: '14px',
});

interface StyledGanttChartTooltipItemProps {
  $firstIndex?: boolean;
}

export const StyledGanttChartTooltipItem =
  styled.p<StyledGanttChartTooltipItemProps>(({ $firstIndex }) => ({
    margin: 0,
    ...($firstIndex && { maxHeight: '16px' }),
  }));
